import pytest
from pathfinding import astar

GRID = [
    [0, 0, 0, 0],
    [1, 1, 0, 1],
    [0, 0, 0, 0],
]


def valid(grid, path, start, goal):
    assert path[0] == start and path[-1] == goal
    for (r1, c1), (r2, c2) in zip(path, path[1:]):
        assert abs(r1 - r2) + abs(c1 - c2) == 1
    assert all(grid[r][c] == 0 for r, c in path)


def test_r1_finds_a_valid_path_around_walls():
    path = astar(GRID, (0, 0), (2, 0))
    assert path is not None
    valid(GRID, path, (0, 0), (2, 0))


def test_r2_path_is_shortest():
    assert len(astar(GRID, (0, 0), (2, 0))) == 7


def test_r3_returns_none_when_blocked():
    assert astar([[0, 1, 0]], (0, 0), (0, 2)) is None


def test_r4_start_equals_goal():
    assert astar(GRID, (0, 0), (0, 0)) == [(0, 0)]


def test_r5_rejects_a_blocked_start():
    with pytest.raises(ValueError):
        astar(GRID, (1, 0), (0, 0))

